--皮肤幻化表（越南语）.xlsx-皮肤组合表-tab_shape_group
GDatatab_shape_group = 
{
	id_1 = { id = 1,name = "Tổ Hợp Vàng Son",skin_male = {{34,36}},skin_female = {{35,37}},position = {{0.3,0.5},{0.7,0.5}},scale = {{1,1}},skill_id = 6101,bullet = "skill_ymcz1",desc = "    Trong thế giới GunPow có một khu rừng, gọi là Rừng Goblin, là nơi sinh sống của nhiều loài thú hoang như lợn rừng, chó rừng, thỏ rừng, và tất nhiên, là nơi cư trú của vô số Goblin. Tại đây có một ngôi trường, chuyên đào tạo dũng sĩ.\n    Bảo vệ kiêm giáo viên của ngôi trường này là một đôi vợ chồng già. Không ai biết tên thật của họ là gì, mọi người đều gọi họ là ông bà một cách trìu mến. Tại đây, các dũng sĩ GunPow đêm ngày miệt mài tập luyện, rèn giũa kỹ thuật bắn của mình.\n    Đột nhiên có một hôm, Thủ Lĩnh Goblin \"Máy Cưa Điên Cuồng\" cho rằng ngôi trường này đã chiếm mất lãnh địa của hắn, thế là hắn dẫn theo binh đoàn Goblin đến phá hoại.\n    Hai ông bà liền cùng Roger và Anna hóa thân kỵ sĩ, cưỡi trên các loại thú rừng, chiến đấu với binh đoàn Goblin.\n"},
	id_2 = { id = 2,name = "Hắc Bạch Vô Thường",skin_male = {{172,179}},skin_female = {{172,179}},position = {{0.65,0.5},{0.35,0.5}},scale = {{0.9,0.9}},skill_id = 6001,bullet = "skill_fh1",desc = "    Thế giới GunPow có hai vị thần nho nhỏ, một vị là Bạch Vô Thường, một vị là Hắc Vô Thường. Hai vị thần này thường ngày hay làm gì nhỉ?\n    Hắc Bạch Vô Thường là thần, cũng là nha sai của âm phủ. Hai vị này tay cầm cùm xích, chuyên bắt hồn ma, có khi cũng thưởng thiện phạt ác.\n    Hắc Vô Thường và Bạch Vô Thường tuy chuyên trách bắt hồn ma, nhưng Hắc Vô Thường chỉ đem lại kiếp nạn cho kẻ ác, còn Bạch Vô Thường tuy gây hoảng sợ và bất an, nhưng cũng đem lại may mắn và tài lộc.\n    Bạch Vô Thường vốn tên là Tạ Tất An, thuộc Dương, mặt luôn tươi cười, thân hình cao ráo gầy gò, sắc mặt trắng bệch, lưỡi dài thò ra khỏi miệng, trên đầu đội chiếc mũ quan, bên trên ghi bốn chữ \"Nhất Kiến Sinh Tài\", đem lại may mắn cho những người biết ơn và tôn kính thần linh.\n    Hắc Vô Thường vốn tên là Phạm Vô Xá, thuộc Âm. Nét mặt hung hãn, thân hình phốp pháp, dáng nhỏ thó đen đúa, trên mũ quan có ghi bốn chữ \"Thiên Hạ Thái Bình\", quyết không tha cho những kẻ phạm tội."},
	id_3 = { id = 3,name = "Như Nước Với Lửa",skin_male = {{196,188}},skin_female = {{196,188}},position = {{0.3,0.5},{0.7,0.4}},scale = {{1,0.9}},skill_id = 6201,bullet = "skill_tb1",desc = "    Chúc Dung và Cộng Công đều là một trong Thập Hoang Đại Thần thời thượng cổ.\n    Chúc Dung cai quản lửa, có thể đem ánh sáng soi rọi khắp thế gian, giúp cây cối xanh tươi, tạo phúc cho dân, nên về sau Chúc Dung được tôn làm thần lửa.\n    Cộng Công cai quản nước, khi vui dùng pháp lực tạo thành mưa dầm, khơi nguồn nước chảy, giúp dân tưới tiêu cấy cày, nhưng cũng có khi nổi giận dâng lũ, khiến dân khốn khổ.\n    Thủy Thần Cộng Công và Hỏa Thần Chúc Dung vốn bất hòa. Thủy Thần Cộng Công cho rằng vạn vật trong thế gian không thể nào thiếu đi nguồn nước, vậy tại sao mọi người chỉ tôn sùng Chúc Dung? Càng nghĩ càng tức, từ đó trong mặt ngoài mặt đều làm khó dễ Chúc Dung.\n    Về sau, hai bên xảy ra mâu thuẫn lớn, thế là một trận chiến kinh thiên động địa đã diễn ra. Thủy Thần Cộng Công chiến bại, giận dữ húc đổ núi Bất Chu, khiến trời nghiêng đất ngửa, cuối cùng Nữ Oa luyện đá vá trời, để lại công tích lưu truyền muôn đời."},
	id_4 = { id = 4,name = "Chiến Thần Robot",skin_male = {{192,202}},skin_female = {{192,202}},position = {{0.65,0.5},{0.35,0.5}},scale = {{1,1}},skill_id = 6401,bullet = "skill_dcsf",desc = "    Năm 2200, Thần Thoại hồi sinh.\n    Ác quỷ trong Thần Thoại lần lượt xuất hiện, sức mạnh của chúng khiến loài người choáng váng.\n    Trong cuộc chiến giằng co này, loài người đã phát hiện ra hai xác Nhân Mã đóng băng.\n    Các nhà khoa học không ngừng nghiên cứu sức mạnh siêu nhiên, chế tạo ra hai robot đời đầu: Kỵ Sĩ Giáp Bạc và Chiến Binh Giáp Bạc.\n"},
	id_5 = { id = 5,name = "Vợ Chồng Son",skin_male = {{183,201}},skin_female = {{183,201}},position = {{0.35,0.5},{0.65,0.5}},scale = {{1,1}},skill_id = 6501,bullet = "skill_gsl",desc = "    Thiết Phiến Công Chúa là công chúa của quốc gia nhỏ.\n    Công chúa từ khi còn nhỏ đã vô cùng xinh đẹp, khi đến tuổi cập kê, quốc vương đã tổ chức một buổi kén rể long trọng cho công chúa. Chuyện này chấn động khắp nơi, vô số người đều lũ lượt kéo đến.\n    Công chúa một lòng tu đạo, muốn tìm một đạo nhân tuấn tú làm chồng, mong sẽ có ngày trở thành một đôi thần tiên quyến lữ.\n    Ngưu Ma Vương lúc này vẫn là một yêu quái quê kệch, vừa xấu xí lại chẳng có chút căn cơ nào. Nhưng một kẻ bị xem thường như hắn, lại sẵn sàng liều mình vì công chúa, nhờ đó vượt qua bao gian khó, lọt đến vòng cuối cùng.\n    Thiết Phiến Công Chúa cảm thấy hắn khá thú vị, nhân một lần cơ duyên, nàng đã lén trao pháp bảo cho Ngưu Ma Vương. Nhờ đó mà Ngưu Ma Vương đã bứt phá thành công, trở thành người chiến thắng, hai người trở thành một đôi."},
	id_6 = { id = 6,name = "Địa Phủ",skin_male = {{189,173}},skin_female = {{189,173}},position = {{0.65,0.35},{0.35,0.5}},scale = {{1,1}},skill_id = 6601,bullet = "skill_ymkj",desc = "\"Tương truyền\", \"Truyền Tin Địa Ngục\" chỉ mở vào lúc nửa đêm.\nNếu trút oán hận vào đó, Thiếu Nữ Địa Ngục sẽ xuất hiện, tống người khiến bạn oán hận vào Địa Ngục.\nĐịa Ngục có đường Hoàng Tuyền, có sông Vong Xuyên, và cầu Nại Hà. Đi qua cầu Nại Hà sẽ đến đài Vọng Hương. Bên đài Vọng Hương có một người bán canh Mạnh Bà. Bên bờ Vong Xuyên có đá Tam Sinh.\nCanh Mạnh Bà sẽ khiến bạn quên đi tất cả. Đá Tam Sinh ghi lại kiếp trước và kiếp này. \nChúng tôi đi qua cầu Nại Hà, ngắm nhìn nhân gian lần cuối ở đài Vọng Hương và uống nước Vong Xuyên.\n \"Đời này có duyên không phận, sao phải cưỡng cầu\"."},
	id_7 = { id = 7,name = "Phổ Độ Chúng Sinh",skin_male = {{186,217}},skin_female = {{186,217}},position = {{0.25,0.5},{0.75,0.5}},scale = {{1,1}},skill_id = 6701,bullet = "skill_chpd",desc = "Tịnh Không Pháp Sư là vị trụ trì đức cao vọng trọng trong Chùa Quan Âm.\nNgày ngày, ông chăm chỉ tụng kinh niệm Phật, nhưng chưa bao giờ cảm nhận được sự chỉ dẫn của Quan Âm.\nMột ngày nọ, Tịnh Không Pháp Sư bỗng ngộ ra: Quan Âm phát nguyện cứu độ chúng sinh, là tín đồ của Quan Âm, ông nên đi khắp thế gian, cảm nhận nỗi khổ của chúng sinh.\nVậy là Tịnh Không Pháp Sư bước vào hành trình phổ độ chúng sinh.\n"},
	id_8 = { id = 8,name = "Phong Thần Diễn Nghĩa",skin_male = {{215,218,187}},skin_female = {{215,218,187}},position = {{0.15,0.5},{0.85,0.5},{0.5,0.5}},scale = {{0.8,0.8,0.8}},skill_id = 6801,bullet = "skill_fsly1",desc = "Phong Thần Diễn Nghĩa (thường gọi là Phong Thần Bảng) là một tiểu thuyết dài tập do Hứa Trung Lâm sáng tác vào thời Minh, hoàn thành trong thời kỳ Long Khánh và Vạn Lịch.\nPhong Thần Diễn Nghĩa gồm một trăm hồi, kể về câu chuyện Vũ Vương phạt Trụ. Ba mươi hồi đầu chủ yếu miêu tả sự tàn bạo của Trụ Vương, Khương Tử Nha quy ẩn, Văn Vương tìm kiếm hiền tài, được Khương Tử Nha phò tá, nhờ đó Vũ Vương mới có thể hoàn thành đại nghiệp thảo phạt Trụ Vương. Bảy mươi hồi còn lại chủ yếu kể về cuộc chiến giữa hai nước Thương và Chu, đồng thời pha trộn cả tranh chấp tôn giáo, Xiển giáo giúp đỡ Chu, Triệt giáo giúp đỡ Thương, mỗi bên sử dụng đạo thuật, sát thương lẫn nhau, kết quả Triệt giáo thất bại, Trụ Vương tàn ác tự thiêu, Vũ Vương giành thiên hạ, phân phong liệt quốc, Khương Tử Nha trở về nước phong thần, để những người có công với quốc gia và các quỷ thần đều có chốn để về.\nTiểu thuyết này, lấy quan điểm lịch sử và chính trị làm nền tảng cho toàn bộ tư tưởng của tác phẩm, pha trộn nhiều tưởng tượng vĩ đại, thể hiện sự ủng hộ và ca ngợi của tác giả đối với các vị minh quân hiền đức, đồng thời thể hiện sự bất mãn và phản kháng đối với hôn quân vô đạo."},
	id_9 = { id = 9,name = "Thuốc Bất Tử",skin_male = {{204,211}},skin_female = {{204,211}},position = {{0.25,0.5},{0.75,0.5}},scale = {{1,1}},skill_id = 6901,bullet = "skill_bmsd1",desc = "Thời cổ đại, trên trời xuất hiện 10 mặt trời, khiến cho mặt đất khô cằn, mọi người đều không thể sinh tồn.\nHậu Nghệ leo lên đỉnh núi Côn Lôn, dùng cung thần bắn hạ 9 mặt trời, giúp con người có thể sinh tồn.\nTây Vương Mẫu cảm tạ công đức của Hậu Nghệ, tặng cho 1 viên Thuốc Bất Tử, uống đơn dược vào sẽ trường sinh bất lão, bay lên thành tiên.\nHậu Nghệ vì không muốn xa người vợ Hằng Nga, nên không uống viên đơn dược, mà là bảo Hằng Nga cất đi.\nTin tức Hậu Nghệ nhận Thuốc Bất Tử bị Bàng Mông biết được, hắn nhân lúc Hậu Nghệ ra ngoài muốn ép Hằng Nga giao ra đơn dược. Cuối cùng Hằng Nga đành nuốt Thuốc Bất Tử.\nSau khi nuốt Thuốc Bất Tử, đột nhiên Hằng Nga trở nên nhẹ tênh rồi bay về phía cung trăng.\n"},
	id_10 = { id = 10,name = "Đao Trảm Quỷ",skin_male = {{79,85}},skin_female = {{80,86}},position = {{0.25,0.5},{0.75,0.5}},scale = {{1,1}},skill_id = 7001,bullet = "skill_zgzr_1",desc = "Người ta kể rằng sau khi mặt trời lặn, những linh hồn ma quỷ sẽ xuất hiện và ăn thịt người. Ngoài ra còn có những thợ săn ma chuyên giết ma quỷ và bảo vệ mọi người.Cuộc sống yên bình và ấm áp của cậu bé đã bị phá hủy sau khi cậu bị một linh hồn ma quỷ tấn công.\nNezuko, cô em gái sống sót cùng cậu, cũng biến thành một con quỷ hung dữ.\nDưới sự hướng dẫn của thợ săn quỷ, cậu bé khao khát trở thành thợ săn quỷ. Cậu và Nezuko, người tuy đã biến thành quỷ nhưng vẫn giữ được sự tỉnh táo, cùng nhau bắt đầu một cuộc hành trình mới.\n"},
	id_11 = { id = 11,name = "Nước Mắt Nhân Ngư",skin_male = {{231,212}},skin_female = {{231,212}},position = {{0.25,0.5},{0.75,0.5}},scale = {{1,1}},skill_id = 7101,bullet = "skill_renyuzhilei",desc = "Giữa đại dương có một tộc người cá, thân người đuôi cá, mỗi khi khóc, nước mắt hóa thành ngọc trai.\nVì thế, tộc người cá này bị con người săn bắt, nô dịch để lấy ngọc trai, thậm chí còn nghĩ đủ cách hành hạ để họ phải rơi lệ.\nCuối cùng, không thể chịu nổi nữa, tộc người cá đã xuất hiện hai thiên tài ma thuật: Thương Tu và Công Chúa Cá Vàng.\nHọ đã cùng nhau dẫn dắt toàn tộc người cá vùng lên phản kháng, giành một cơ hội sinh tồn.\n"},
	id_13 = { id = 13,name = "Đứa Con Của Bão",skin_male = {{75,69}},skin_female = {{76,70}},position = {{0.7,0.5},{0.3,0.5}},scale = {{1,1}},skill_id = 7301,bullet = "skill_fbzh",desc = "Thuyền Trưởng Bão Tố là người hiểu rõ biển cả nhất trên đại dương này.\nÔng dám lái con tàu của mình băng qua cơn bão khủng khiếp nhất trên biển để khám phá hải trình mới.\nPhù Thủy Mèo và Pháo Thủ Mèo cũng đi theo Thuyền Trưởng Bão Tố chiến đấu với biển cả.\nTrong một lần vượt bão, Thuyền Trưởng Bão Tố đã gặp và yêu Công Chúa Thủy Triều.\nKhông thể ngăn cản người yêu mạo hiểm, Công Chúa Thủy Triều cuối cùng cũng tham gia cuộc phiêu lưu."},
	id_14 = { id = 14,name = "Cuộc Chiến Thánh Ma",skin_male = {{238,236}},skin_female = {{238,236}},position = {{0.65,0.5},{0.35,0.5}},scale = {{0.7,0.7}},skill_id = 7401,bullet = "skill_smby",desc = "Trước kia, Vân và Vụ là sư huynh đệ đồng môn cùng bái sư học nghệ.\nThế nhưng, gia tộc của Vụ vì chí bảo mà bị diệt môn, chỉ còn mình Vụ mang theo chí bảo trốn thoát.\nVì báo thù, cũng vì không muốn liên lụy sư môn.\nVụ tự hủy dung nhan gia nhập Ma Giáo.\nCuối cùng, Vụ trở thành chủ nhân Ma Giáo, được gọi là Ma Thần - Vụ.\nCòn Vân vì sự ra đi của Vụ mà phấn đấu tu luyện, cuối cùng trở thành Kiếm Thánh\n"},
}
